// Photo asset "sidewalk-sign" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/sidewalk-sign.js"></script>
//   <img data-asset="sidewalk-sign" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "sidewalk-sign": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="sidewalk-sign"]').forEach(function (img) { img.src = window.ASSETS["sidewalk-sign"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
